create table if not exists private.moderator_scopes(user_id uuid primary key references auth.users(id),scopes text[] not null default '{}',updated_by uuid not null,updated_at timestamptz not null default now(),check(scopes<@array['auction','advice','dream']::text[]));
create table if not exists private.member_discipline(user_id uuid primary key references auth.users(id),state text not null check(state in('warning','banned','clear')),reason text not null,actor uuid not null,updated_at timestamptz not null default now());
create table if not exists private.support_messages(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),body text not null check(length(body) between 10 and 2000),resolved boolean not null default false,created_at timestamptz not null default now());
create table if not exists private.online_browsers(visitor_hash text primary key,path text not null,last_seen timestamptz not null default now());
create index if not exists online_browsers_recent on private.online_browsers(last_seen desc);
alter table private.moderator_scopes enable row level security;alter table private.member_discipline enable row level security;alter table private.support_messages enable row level security;alter table private.online_browsers enable row level security;
revoke all on private.moderator_scopes,private.member_discipline,private.support_messages,private.online_browsers from public,anon,authenticated;
create or replace function private.can_moderate(p_kind text) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and (coalesce(private.advice_admin(),false) or exists(select 1 from private.moderator_scopes where user_id=auth.uid() and (case when p_kind='dream_comment' then 'dream' else p_kind end)=any(scopes)));$$;
revoke all on function private.can_moderate(text) from public;grant execute on function private.can_moderate(text) to authenticated;
create or replace function private.guard_banned_member() returns trigger language plpgsql security definer set search_path='' as $$begin if auth.uid() is not null and exists(select 1 from private.member_discipline where user_id=auth.uid() and state='banned') then if TG_TABLE_NAME='auction_lots' and TG_OP='UPDATE' and (to_jsonb(new)-array['seller_done','buyer_done'])=(to_jsonb(old)-array['seller_done','buyer_done']) then return new;end if;raise exception 'COMMUNITY_PARTICIPATION_BANNED';end if;return new;end;$$;
revoke all on function private.guard_banned_member() from public,anon,authenticated;
do $$declare t text;begin foreach t in array array['public.slot_claims','public.advice_posts','public.advice_votes','public.advice_bookmarks','public.dream_posts','public.dream_comments','public.dream_reactions','private.auction_lots','private.auction_bids','private.auction_ratings','private.auction_accounts','private.frequency_comments','public.slot_likes','public.canvas_guilds','public.canvas_guild_members','public.canvas_battle_votes','public.community_challenge_votes','storage.objects'] loop if not exists(select 1 from pg_trigger where tgname='celltalk_member_guard' and tgrelid=t::regclass) then execute format('create trigger celltalk_member_guard before insert or update on %s for each row execute function private.guard_banned_member()',t);end if;end loop;end;$$;
-- Keep all legacy global checks intact, except the content API's kind-scoped authorization.
do $$declare s text;begin s:=pg_get_functiondef('private.admin_content(text,jsonb)'::regprocedure);s:=replace(s,'not coalesce(private.advice_admin(),false)','not coalesce(private.can_moderate(kind),false)');execute s;end;$$;
create or replace function private.browser_heartbeat(p_path text,p_visitor uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if p_visitor is null or p_path is null or length(p_path)>100 or p_path ~ '/admin' then return;end if;
 if p_path<>'/' and p_path !~ '^/(ar|en)/(advice|dreams|auctions|comedy-will|frequencies)(/[0-9a-f-]{36})?/?$' then return;end if;
 insert into private.online_browsers(visitor_hash,path) values(md5(p_visitor::text||(clock_timestamp() at time zone 'Africa/Cairo')::date::text),p_path) on conflict(visitor_hash) do update set last_seen=now(),path=excluded.path;
end;$$;
revoke all on function private.browser_heartbeat(text,uuid) from public;grant execute on function private.browser_heartbeat(text,uuid) to anon,authenticated;
create or replace function public.browser_heartbeat(p_path text,p_visitor uuid) returns void language sql security invoker set search_path='' return private.browser_heartbeat(p_path,p_visitor);
revoke all on function public.browser_heartbeat(text,uuid) from public;grant execute on function public.browser_heartbeat(text,uuid) to anon,authenticated;
do $$begin if not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='auction_scoped_moderator_read') then execute 'create policy auction_scoped_moderator_read on storage.objects for select to authenticated using(bucket_id=''auction-media'' and private.can_moderate(''auction''))';end if;end;$$;
